package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import net.officefloor.hq.app.client.Currency;

/**
 * A client's statement: all of their invoices, each with the project it is for and how much is left
 * to pay, the same invoices grouped by job with what is owed on each job, and the total still owed
 * (what is left to pay across their sent invoices; drafts and void ones are not owed). For the printable
 * summary it also gives the total invoiced on those owed invoices and how much of that has been paid,
 * so the total still owed is what was invoiced less what was paid. It also shows the tax (sales tax and
 * levy) on each job and across the whole statement, again leaving out drafts and void invoices. All of it
 * is in the client's currency.
 */
public record ClientStatementResponse(Long clientId, String clientName, Currency currency, List<Line> invoices, List<Job> jobs,
        BigDecimal invoiced, BigDecimal paid, BigDecimal outstanding, BigDecimal tax) {

    static ClientStatementResponse from(Long clientId, String clientName, Currency currency, List<Line> invoices) {
        Map<Long, List<Line>> byProject = new LinkedHashMap<>();
        invoices.forEach(l -> byProject.computeIfAbsent(l.projectId(), id -> new ArrayList<>()).add(l));
        List<Job> jobs = byProject.values().stream()
                .map(lines -> new Job(lines.get(0).projectId(), lines.get(0).projectName(), lines, owed(lines), sum(lines, Line::tax)))
                .toList();
        BigDecimal outstanding = owed(invoices);
        BigDecimal invoiced = sum(invoices, Line::amount);
        return new ClientStatementResponse(clientId, clientName, currency, invoices, jobs, invoiced,
                invoiced.subtract(outstanding), outstanding, sum(invoices, Line::tax));
    }

    /** What is left to pay across the given invoices, leaving out drafts and void ones. */
    private static BigDecimal owed(List<Line> lines) {
        return sum(lines, Line::amountDue);
    }

    /** Adds up the given figure across the invoices that are owed, leaving out drafts and void ones. */
    private static BigDecimal sum(List<Line> lines, Function<Line, BigDecimal> figure) {
        return lines.stream()
                .filter(l -> l.status() != InvoiceStatus.DRAFT && !l.status().isClosedUnpaid())
                .map(figure)
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
    }

    /** One job on a statement: its invoices, the subtotal still owed on them and the tax charged on them. */
    public record Job(Long projectId, String projectName, List<Line> invoices, BigDecimal subtotal, BigDecimal tax) {
    }

    /** One invoice on a statement; its tax is the sales tax and levy on it. */
    public record Line(Long id, Long projectId, String projectName, BigDecimal amount, InvoiceStatus status,
            LocalDate issuedDate, LocalDate dueDate, BigDecimal amountDue, BigDecimal tax) {

        static Line from(Invoice invoice, BigDecimal paid, BigDecimal credited) {
            return new Line(invoice.getId(), invoice.getProject().getId(), invoice.getProject().getName(),
                    invoice.getAmount(), invoice.statusFor(paid, credited), invoice.getIssuedDate(), invoice.getDueDate(),
                    invoice.amountDue(paid, credited), invoice.getTax().add(invoice.getLevy()));
        }
    }
}
package net.officefloor.hq.app.invoice;

import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** A client's statement: every invoice raised across their projects and the total they still owe. */
@RestController
@RequestMapping("/api/clients/{clientId}/statement")
public class ClientStatementController {

    private final InvoiceService service;

    public ClientStatementController(InvoiceService service) {
        this.service = service;
    }

    @GetMapping
    public ClientStatementResponse get(@PathVariable Long clientId) {
        return service.statementForClient(clientId);
    }
}
import { CurrencyPipe } from '@angular/common';
import { Component, computed, inject, input } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { RouterLink } from '@angular/router';
import { InvoiceService } from './invoice.service';

// A client's statement: every invoice across the client's projects grouped by job, how much is left to
// pay on each, a subtotal still owed and the tax per job, the tax across the statement, and the total the client still owes. Drafts are listed but do not count towards what is owed.
// It is laid out to print cleanly: a summary of what was invoiced, what was paid and the grand total owed,
// with the app's navigation and the page's controls left off the printed copy.
@Component({
  selector: 'app-client-statement',
  imports: [CurrencyPipe, RouterLink],
  styles: `
    .statement-actions {
      display: flex;
      gap: 1rem;
      align-items: center;
    }
    .statement-summary {
      display: grid;
      grid-template-columns: max-content max-content;
      gap: 0.25rem 1.5rem;
    }
    .statement-summary dd {
      margin: 0;
      text-align: right;
    }
    .statement-grand-total {
      font-weight: bold;
      border-top: 1px solid currentColor;
      padding-top: 0.25rem;
    }
    table {
      border-collapse: collapse;
    }
    th,
    td {
      padding: 0.25rem 0.5rem;
      text-align: left;
    }
    @media print {
      .statement-actions {
        display: none;
      }
      table {
        width: 100%;
      }
      tbody {
        break-inside: avoid;
      }
    }
  `,
  template: `
    <div class="statement-actions">
      <a [routerLink]="['/clients', clientId()]" data-testid="client-statement-back">Back to client</a>
      @if (statement.hasValue()) {
        <button type="button" data-testid="statement-print" (click)="print()">Print statement</button>
      }
    </div>
    @if (statement.error()) {
      <p role="alert" data-testid="client-statement-error">Could not load the statement.</p>
    } @else if (statement.value(); as s) {
      <article data-testid="statement-print-view" aria-labelledby="statement-heading">
        <h1 id="statement-heading" data-testid="client-statement-name">Statement for {{ s.clientName }}</h1>
        <section aria-labelledby="statement-summary-heading" data-testid="statement-summary">
          <h2 id="statement-summary-heading">Summary</h2>
          <dl class="statement-summary">
            <dt>Total invoiced</dt>
            <dd data-testid="statement-total-invoiced">{{ s.invoiced | currency: s.currency : 'symbol' : '1.2-2' : 'en-US' }}</dd>
            <dt>Tax</dt>
            <dd data-testid="client-statement-tax-total">{{ s.tax | currency: s.currency : 'symbol' : '1.2-2' : 'en-US' }}</dd>
            <dt>Less paid</dt>
            <dd data-testid="statement-total-paid">{{ s.paid | currency: s.currency : 'symbol' : '1.2-2' : 'en-US' }}</dd>
            <dt class="statement-grand-total">Grand total owed</dt>
            <dd class="statement-grand-total" data-testid="statement-grand-total">{{ s.outstanding | currency: s.currency : 'symbol' : '1.2-2' : 'en-US' }}</dd>
          </dl>
        </section>
        @if (s.invoices.length === 0) {
          <p data-testid="client-statement-empty">No invoices yet.</p>
        } @else {
          <table data-testid="client-statement-table">
            <caption>Invoices for {{ s.clientName }}</caption>
            <thead>
              <tr>
                <th scope="col">Invoice</th>
                <th scope="col">Job</th>
                <th scope="col">Status</th>
                <th scope="col">Issued</th>
                <th scope="col">Due</th>
                <th scope="col">Amount</th>
                <th scope="col">Tax</th>
                <th scope="col">Left to pay</th>
              </tr>
            </thead>
            @for (job of s.jobs; track job.projectId) {
              <tbody [attr.data-testid]="'statement-project-' + job.projectId">
                <tr>
                  <th scope="colgroup" colspan="8" data-testid="statement-project-name">{{ job.projectName }}</th>
                </tr>
                @for (i of job.invoices; track i.id) {
                  <tr [attr.data-testid]="'statement-invoice-row-' + i.id">
                    <td data-testid="statement-invoice-id">
                      <a
                        [routerLink]="['/projects', i.projectId, 'invoices', i.id]"
                        [attr.data-testid]="'statement-invoice-open-' + i.id"
                        [attr.aria-label]="'Open invoice #' + i.id"
                        >#{{ i.id }}</a
                      >
                    </td>
                    <td data-testid="statement-invoice-project">{{ i.projectName }}</td>
                    <td data-testid="statement-invoice-status">{{ i.status }}</td>
                    <td data-testid="statement-invoice-issued">{{ i.issuedDate }}</td>
                    <td data-testid="statement-invoice-due">{{ i.dueDate }}</td>
                    <td data-testid="statement-invoice-amount">{{ i.amount | currency: s.currency : 'symbol' : '1.2-2' : 'en-US' }}</td>
                    <td data-testid="statement-invoice-tax">{{ i.tax | currency: s.currency : 'symbol' : '1.2-2' : 'en-US' }}</td>
                    <td data-testid="statement-invoice-due-amount">{{ i.amountDue | currency: s.currency : 'symbol' : '1.2-2' : 'en-US' }}</td>
                  </tr>
                }
                <tr>
                  <th scope="row" colspan="6">Tax on {{ job.projectName }}</th>
                  <td data-testid="statement-project-tax">{{ job.tax | currency: s.currency : 'symbol' : '1.2-2' : 'en-US' }}</td>
                  <td></td>
                </tr>
                <tr>
                  <th scope="row" colspan="7">Subtotal owed on {{ job.projectName }}</th>
                  <td data-testid="statement-project-subtotal">{{ job.subtotal | currency: s.currency : 'symbol' : '1.2-2' : 'en-US' }}</td>
                </tr>
              </tbody>
            }
          </table>
        }
        <p>
          Total owed:
          <strong data-testid="client-outstanding-total">{{ s.outstanding | currency: s.currency : 'symbol' : '1.2-2' : 'en-US' }}</strong>
        </p>
      </article>
    }
  `,
})
export class ClientStatement {
  private readonly service = inject(InvoiceService);

  /** Bound from the `:id` route parameter. */
  readonly id = input.required<string>();
  protected readonly clientId = computed(() => Number(this.id()));

  protected readonly statement = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.service.statementForClient(params),
  });

  protected print(): void {
    window.print();
  }
}
