            DepositApplicationRepository applications, InvoiceRepository invoices, PaymentRepository payments,
            CreditNoteRepository creditNotes, RefundRepository refunds) {
        this.clients = clients;
        this.deposits = deposits;
        this.applications = applications;
        this.invoices = invoices;
        this.payments = payments;
        this.creditNotes = creditNotes;
        this.refunds = refunds;
    }

    /**
     * Works out how much credit a client has to spend. A deposit is unused until it is put toward invoices. A credit
     * note is used only as far as it was needed to settle its invoice once payments are counted; anything beyond
     * that (say, a credit on an invoice already paid in full, or on one since cancelled) is still the client's to spend.
     * Whatever has been refunded to the client is no longer theirs to spend.
     */
    @Transactional(readOnly = true)
    public ClientCreditResponse available(Long clientId) {
        if (!clients.existsById(clientId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
        }
        BigDecimal held = deposits.sumAmountByClientId(clientId)
                .subtract(applications.sumAmountByClientId(clientId))
                .subtract(refunds.sumFromDepositsByClientId(clientId)).setScale(2).max(ZERO);
        BigDecimal unusedCredit = unusedCreditNotes(clientId)
                .subtract(refunds.sumFromCreditNotesByClientId(clientId)).setScale(2).max(ZERO);
        return new ClientCreditResponse(held, unusedCredit, held.add(unusedCredit));
    }

    private BigDecimal unusedCreditNotes(Long clientId) {
        List<Invoice> clientInvoices = invoices.findByClientIdWithProject(clientId);
        List<Long> ids = clientInvoices.stream().map(Invoice::getId).toList();
        if (ids.isEmpty()) {
            return ZERO;
        }
        Map<Long, BigDecimal> credited = creditNotes.sumAmountByInvoiceIds(ids).stream().collect(Collectors.toMap(
                CreditNoteRepository.InvoiceCreditedTotal::getInvoiceId,
                CreditNoteRepository.InvoiceCreditedTotal::getCredited));
        if (credited.isEmpty()) {
            return ZERO;
        }
        Map<Long, BigDecimal> paid = payments.sumAmountByInvoiceIds(ids).stream().collect(Collectors.toMap(
                PaymentRepository.InvoicePaidTotal::getInvoiceId, PaymentRepository.InvoicePaidTotal::getPaid));
        BigDecimal unused = ZERO;
        for (Invoice invoice : clientInvoices) {
            BigDecimal credit = credited.get(invoice.getId());
            if (credit == null) {
                continue;
            }
            // A cancelled invoice is no longer owed, so none of its credit went toward settling it.
            BigDecimal owed = invoice.getStatus() == InvoiceStatus.VOID ? ZERO
                    : invoice.getAmount().subtract(paid.getOrDefault(invoice.getId(), ZERO)).max(ZERO);
            unused = unused.add(credit.subtract(credit.min(owed)));
        }
        return unused.setScale(2);
    }
}
package net.officefloor.hq.app.payment;


/** An amount a client has paid against an invoice on a given day. */
@Entity
@Table(name = "payment")
public class Payment {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "invoice_id", nullable = false)
    private Long invoiceId;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal amount;

    @Column(name = "paid_date", nullable = false)
    private LocalDate date;

    /** The lump payment this was split from; null when paid against the invoice on its own. */
    @Column(name = "client_payment_id")
    private Long clientPaymentId;

    /** The deposit application this was put toward the invoice from; null when it was not paid from deposits. */
    @Column(name = "deposit_application_id")
    private Long depositApplicationId;

    protected Payment() {
    }

    public Payment(Long invoiceId, BigDecimal amount, LocalDate date) {
        this.invoiceId = invoiceId;
        this.amount = amount.setScale(2);
        this.date = date;
    }

    public Payment(Long invoiceId, BigDecimal amount, LocalDate date, Long clientPaymentId) {
        this(invoiceId, amount, date);
        this.clientPaymentId = clientPaymentId;
    }

    /** A share of a client's held deposits put toward an invoice. */
    public static Payment fromDeposits(Long invoiceId, BigDecimal amount, LocalDate date, Long depositApplicationId) {
        Payment payment = new Payment(invoiceId, amount, date);
        payment.depositApplicationId = depositApplicationId;
        return payment;
    }

    public Long getId() {
        return id;
    }

    public Long getInvoiceId() {
        return invoiceId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public Long getClientPaymentId() {
        return clientPaymentId;
    }

    public Long getDepositApplicationId() {
        return depositApplicationId;
    }
}
package net.officefloor.hq.app.payment;


public interface PaymentRepository extends JpaRepository<Payment, Long> {

    /** An invoice's payments, oldest first. */
    List<Payment> findByInvoiceIdOrderByDateAscIdAsc(Long invoiceId);

    /** Total paid against an invoice (zero when nothing has been paid). */
    @Query("SELECT COALESCE(SUM(p.amount), 0) FROM Payment p WHERE p.invoiceId = :invoiceId")
    BigDecimal sumAmountByInvoiceId(Long invoiceId);

    /** Total paid against every invoice with any of the given statuses (zero when nothing has been paid). */
    @Query("SELECT COALESCE(SUM(p.amount), 0) FROM Payment p, Invoice i"
            + " WHERE p.invoiceId = i.id AND i.status IN :statuses")
    BigDecimal sumAmountByInvoiceStatusIn(Collection<InvoiceStatus> statuses);

    /** Total paid against invoices with any of the given statuses, per client; clients with none are left out. */
    @Query("SELECT pr.client.id AS clientId, SUM(p.amount) AS total FROM Payment p, Invoice i JOIN i.project pr"
            + " WHERE p.invoiceId = i.id AND i.status IN :statuses GROUP BY pr.client.id")
    List<InvoiceRepository.ClientTotal> sumAmountByInvoiceStatusInPerClient(Collection<InvoiceStatus> statuses);

    /** Total paid against each of the given invoices; invoices with no payments are left out. */
    @Query("SELECT p.invoiceId AS invoiceId, SUM(p.amount) AS paid FROM Payment p"
            + " WHERE p.invoiceId IN :invoiceIds GROUP BY p.invoiceId")
    List<InvoicePaidTotal> sumAmountByInvoiceIds(Collection<Long> invoiceIds);

    /** How much has been paid against one invoice. */
    interface InvoicePaidTotal {
        Long getInvoiceId();

        BigDecimal getPaid();
    }
}
package net.officefloor.hq.app.creditnote;


public interface CreditNoteRepository extends JpaRepository<CreditNote, Long> {

    /** An invoice's credit notes, oldest first. */
    List<CreditNote> findByInvoiceIdOrderByIdAsc(Long invoiceId);

    /** Total credited against an invoice (zero when nothing has been credited). */
    @Query("SELECT COALESCE(SUM(c.amount), 0) FROM CreditNote c WHERE c.invoiceId = :invoiceId")
    BigDecimal sumAmountByInvoiceId(Long invoiceId);

    /** Total credited against invoices with any of the given statuses, per client; clients with none are left out. */
    @Query("SELECT pr.client.id AS clientId, SUM(c.amount) AS total FROM CreditNote c, Invoice i JOIN i.project pr"
            + " WHERE c.invoiceId = i.id AND i.status IN :statuses GROUP BY pr.client.id")
    List<InvoiceRepository.ClientTotal> sumAmountByInvoiceStatusInPerClient(Collection<InvoiceStatus> statuses);

    /** Total credited against each of the given invoices; invoices with no credit notes are left out. */
    @Query("SELECT c.invoiceId AS invoiceId, SUM(c.amount) AS credited FROM CreditNote c"
            + " WHERE c.invoiceId IN :invoiceIds GROUP BY c.invoiceId")
    List<InvoiceCreditedTotal> sumAmountByInvoiceIds(Collection<Long> invoiceIds);

    /** How much has been credited against one invoice. */
    interface InvoiceCreditedTotal {
        Long getInvoiceId();

        BigDecimal getCredited();
    }
}
